-- C3/C4: de laatste hardgecodeerde teksten naar het CMS.
--
-- Drie nieuwe pagina's (/klantverhalen, /inzichten, /privacy) en een reeks
-- nieuwe velden op contact, over-ons en werken-bij. De site rendert ook zonder
-- dit script -- ontbreekt een sleutel, dan valt hij terug op de seed -- maar de
-- admin toont alleen wat in de tabel staat. Zonder deze rijen zijn de drie
-- nieuwe pagina's niet te bewerken, en zouden de nieuwe velden op de bestaande
-- pagina's als leeg veld in de editor verschijnen. Wie dan opslaat, slaat een
-- lege string op, en die wint van de seed ("leeg is echt leeg"). Dus draaien.
--
-- Draai in de Supabase SQL Editor. Terugvalkopie eerst:
--
--   create table if not exists _backup_c34 as select id, data from cms_paginas;


-- ---------- 1. dode sleutel op de homepage ----------
-- 'waaromTitel' stond als bewerkbaar veld in de admin maar werd nergens
-- gerenderd; het is uit PAGE_FIELDS verwijderd.
update cms_paginas set data = data - 'waaromTitel'
 where slug = 'home' and data ? 'waaromTitel';

-- ---------- 2. drie nieuwe pagina's ----------
insert into cms_paginas (slug, titel, status, data)
values ('klantverhalen', 'Klantverhalen', 'live', '{"metaTitle": "Klantverhalen: resultaat dat je kunt navragen", "metaDescription": "Verhalen van organisaties in de publieke sector, mobiliteit, banken, zorg en manufacturing, verteld met de cijfers erbij.", "heroKicker": "Klantverhalen", "heroTitleStart": "Resultaat dat je kunt ", "heroAccent": "navragen", "heroTitleEnd": ".", "heroLead": "Business-impact, geen technische anekdote. Hier laten we zien wat er daadwerkelijk verandert bij een klant als strategie, Mendix en AI samenkomen: minder handwerk, snellere processen, meetbaar resultaat.", "uitgelichtKicker": "Uitgelicht", "beloftesKicker": "Onze sectoren", "beloftesTitel": "Nog geen klantverhaal in jouw sector? Dit is wat je kunt verwachten.", "beloftesIntro": "We werken pas kort genoeg samen met organisaties als Moove om al hun verhaal te kunnen delen. De rest volgt. Hieronder alvast het type resultaat dat we per sector al aantoonbaar leveren.", "ctaTitel": "Herken je jouw vraagstuk in deze verhalen?"}'::jsonb)
on conflict (slug) do update set data = excluded.data || cms_paginas.data;
insert into cms_paginas (slug, titel, status, data)
values ('inzichten', 'Inzichten', 'live', '{"metaTitle": "Inzichten: kennis die je morgen kunt gebruiken", "metaDescription": "Praktische artikelen over Mendix, AI en digitale strategie, geschreven vanuit de vraagstukken van onze vijf sectoren, zonder jargon.", "heroKicker": "Inzichten", "heroTitleStart": "Kennis die je ", "heroAccent": "morgen", "heroTitleEnd": " kunt gebruiken.", "heroLead": "Sectorkennis die je vooruit denkt. Praktijkervaring uit projecten bij gemeenten, banken, zorginstellingen en mobiliteitsbedrijven, vertaald naar artikelen die je direct kan gebruiken, geen gerecycled nieuws.", "leadTitel": "Blijf voorop met onze inzichten", "leadTekst": "Eén mail per maand met onze scherpste inzichten over technologie in jouw sector. Geen sales, uitschrijven kan altijd.", "artikelLeadTitel": "Dit soort inzichten, één keer per maand", "artikelLeadTekst": "Laat je e-mail achter en ontvang onze scherpste inzichten over technologie in jouw sector. Geen sales, uitschrijven kan altijd."}'::jsonb)
on conflict (slug) do update set data = excluded.data || cms_paginas.data;
insert into cms_paginas (slug, titel, status, data)
values ('privacy', 'Privacybeleid', 'live', '{"metaTitle": "Privacybeleid", "metaDescription": "Hoe The New Wave IT B.V. persoonsgegevens verzamelt, gebruikt, deelt en beschermt in overeenstemming met de AVG.", "heroTitel": "Privacy Policy", "heroLead": "Hoe wij persoonsgegevens verzamelen, gebruiken, delen en beschermen in relatie tot onze website, in overeenstemming met de AVG.", "body": "<p>Dit is de Privacy Policy van The New Wave IT B.V. (hierna te noemen “The New Wave IT”, “wij,” “ons” of “onze”), statutair gevestigd op Havixhorst 100, Alphen aan den Rijn en ingeschreven bij de Kamer van Koophandel onder nummer 90830490. Ons kantoor bezoek je op Ganzenmarkt 6, Utrecht. Deze Privacy Policy legt uit hoe wij gegevens verzamelen, gebruiken, delen en beschermen in relatie tot onze website <a href=\"https://www.thenewwaveit.com\">http://www.thenewwaveit.com</a> (de “Website”). Wij verzamelen deze gegevens wanneer je onze Website bezoekt met je computer, tablet, telefoon of smartwatch (“Computer”). Wij verwerken persoonsgegevens op een manier welke in overeenstemming is met de Algemene Verordening Gegevensbescherming, inclusief uitvoeringswet van deze verordening, of de voorafgaande wetgeving van de Wet Bescherming Persoonsgegevens en eventuele toekomstige wijzigingen (de “AVG”), de telecommunicatiewet en de andere op dit moment geldende privacywetgeving.</p>\n<p>Door onze Website te gebruiken begrijp je en ga je akkoord met het verzamelen en gebruiken van informatie in overeenstemming met deze Privacy Policy. Onze Privacy Policy is van toepassing op alle bezoekers, gebruikers en alle anderen die de toegang hebben tot de Website (“Gebruikers”).</p>\n<h2>Wat voor gegevens verzamelen wij?</h2>\n<p>Wij verzamelen persoonsgegevens die je ons verstrekt. Een persoonsgegeven betreft informatie over een geïdentificeerde of identificeerbare natuurlijke persoon. Denk daarbij aan de volgende gegevens:</p>\n<ul><li>Communicatie tussen The New Wave IT en jou (wij mogen je dienst-gerelateerde e-mails sturen).</li></ul>\n<h2>Log file informatie</h2>\n<p>Wij verzamelen alleen informatie die je browser stuurt als je onze Website bezoekt wanneer dit noodzakelijk is voor het goed functioneren van de Website. Onder het goed functioneren van de Website verstaan wij met name het beschermen van de Website tegen handelingen die de veiligheid van de Website en van je Computer in gevaar kunnen brengen. Dit logbestand kan informatie bevatten zoals je IP-adres, browser-type, browser-versie, de pagina’s van onze Website die je bezoekt, de tijd en datum van je bezoek, de tijd die je op deze pagina’s doorbrengt en andere statistieken.</p>\n<h2>Analytische diensten</h2>\n<p>Wij maken gebruik van analytische diensten van derden. Deze helpen ons om ons verkeer en trends van de Website te meten. De tools verzamelen informatie die je Computer verstuurt: onze Website, de webpagina’s die je bezoekt, add-ons en andere informatie die ons helpt de Website te verbeteren. Deze tools gebruiken ‘cookies’. Dat zijn eenvoudige tekstbestanden op je harde schijf of in het geheugen van je Computer. Ze kunnen je Computer of de bestanden die erop staan niet beschadigen, en verzamelen anoniem informatie over je log-informatie en log-gedrag. Wij gebruiken deze informatie samen met informatie van andere Gebruikers. Daardoor kunnen wij je niet als individu herkennen. Wij gebruiken voor onze analytische diensten Google Analytics. Google Analytics plaatst een permanent cookie in je webbrowser om je te herkennen, en deelt je gegevens met Google. Wij delen alleen gegevens met Google die wij op basis van de AVG mogen delen met Google. Je voorkomt die herkenning volledig door de cookies in je browser uit te schakelen.</p>\n<h2>Doeleinden verwerking gegevens</h2>\n<p>Door onze diensten te gebruiken laat je bepaalde gegevens bij ons achter, bijvoorbeeld door het aanmaken van een account. Het kan dan gaan om gegevens zoals naam, e-mailadres, woonplaats, telefoonnummer en betaalgegevens. The New Wave IT verzamelt en verwerkt deze gegevens om onze diensten toegankelijk te maken. Wij verzamelen ook informatie over je Computer (zoals IP-adres, browsertype en besturingssysteem), zodat wij onze diensten kunnen verbeteren. Wij geven de persoonsgegevens niet aan derden, tenzij de wet- en regelgeving ons daartoe verplicht.</p>\n<h2>Rechtsgrond verwerking gegevens</h2>\n<p>Er zijn meerdere grondslagen op basis waarvan The New Wave IT persoonsgegevens kan verwerken. Dit zijn: de uitvoering van een overeenkomst, het gerechtvaardigd belang, op grond van een wettelijke verplichting of op grond van jouw toestemming. We verwerken je persoonsgegevens alleen voor zover dat nodig is om het doel te behalen waarvoor we ze verzamelen.</p>\n<h2>Hoe gebruiken wij deze informatie?</h2>\n<p>Alle informatie die wij verzamelen gebruiken wij om onze Website te ondersteunen en verbeteren.</p>\n<h2>Hoe delen wij deze informatie?</h2>\n<p>Wij verhuren of verkopen je (persoons)gegevens niet aan derden.</p>\n<h2>Zeggenschapswijziging</h2>\n<p>Wanneer The New Wave IT of een deel daarvan wordt verkocht of overgedragen, of activa van ons bij een andere organisatie terechtkomen (bijvoorbeeld als gevolg van een fusie, overname, faillissement, ontbinding of liquidatie), dan kunnen gegevens die via de Website zijn verzameld onder de verkochte of overgedragen zaken vallen. De koper of verkrijger zal de afspraken in deze Privacy Policy moeten opvolgen.</p>\n<h2>Wettelijk verzoek en voorkoming schade</h2>\n<p>Op grond van een wettelijk verzoek mogen wij toegang krijgen tot je informatie en die bewaren en/of delen in antwoord op zo’n verzoek (zoals een huiszoekingsbevel, gerechtelijk bevel of een dagvaarding). Wij mogen je informatie ook bewaren en/of delen wanneer wij denken dat dat nodig is om fraude of andere illegale activiteiten op te sporen, te voorkomen en aan te kaarten, en om ons, jou en anderen te beschermen. Informatie die wij over je ontvangen mogen wij openen, bewerken en langer bewaren wanneer dat nodig is vanwege een juridisch verzoek of verplichting, een onderzoek naar onze voorwaarden of beleid, of om anderszins schade te voorkomen.</p>\n<h2>Beveiliging</h2>\n<p>The New Wave IT heeft passende technische en organisatorische maatregelen genomen om je gegevens te beveiligen tegen verlies of tegen enige vorm van onrechtmatige verwerking. Die maatregelen beveiligen de informatie die via de Website binnenkomt. Toch kan The New Wave IT niet garanderen dat niemand de informatie op de Website opent, onthult, verandert of vernietigt. Je beheert zelf de e-mails tussen jou en The New Wave IT. Wij zijn niet verantwoordelijk voor de functionaliteit, privacy of veiligheidsmaatregelen van enige andere organisatie.</p>\n<h2>Internationale overdracht</h2>\n<p>Je informatie kan terechtkomen op computers of servers buiten Nederland en/of de EU, waar andere wetten over gegevensbescherming gelden. Wij spannen ons in om je persoonsgegevens ook buiten de EU juridisch juist en zorgvuldig te laten verwerken.</p>\n<h2>Bewaartermijn</h2>\n<p>In overeenstemming met de AVG en de overige relevante wetgeving, bewaart The New Wave IT persoonsgegevens niet langer dan noodzakelijk is voor de verwezenlijking van de doeleinden waarvoor wij ze verzamelen of verwerken, tenzij een wettelijke bepaling ons tot langer bewaren verplicht. Wil je weten hoelang wij jouw persoonsgegevens precies bewaren, neem dan contact op via <a href=\"mailto:hello@thenewwaveit.com\">hello@thenewwaveit.com</a>.</p>\n<h2>Recht op inzage, correcties, recht op bezwaar en recht op dataportabiliteit</h2>\n<p>Wil je je persoonsgegevens inzien, wijzigen of verwijderen, of wil je ze geheel of gedeeltelijk laten overdragen aan jezelf of aan een derde? Neem dan contact op met The New Wave IT via <a href=\"mailto:hello@thenewwaveit.com\">hello@thenewwaveit.com</a> of een brief sturen aan:</p>\n<address>The New Wave IT B.V.<br>Havixhorst 100<br>2402 MT, Alphen aan den Rijn</address>\n<h2>Applicaties, websites en diensten van derden</h2>\n<p>Wij zijn niet verantwoordelijk voor de praktijken van applicaties, websites of services van derden die gelinkt zijn naar of van onze Website, waaronder de informatie of inhoud die bijgaand is. Onze Privacy Policy geldt niet zodra je via een link van onze Website naar een andere applicatie, website of service gaat. Wat je daar doet valt onder de regels en het beleid van die derde, ook als de link op onze Website stond.</p>\n<h2>Privacy van kinderen</h2>\n<p>Onze Website vraagt niet specifiek en bewust om gegevens van personen jonger dan 16 jaar (“Kinderen”). Deze leeftijd kan variëren in elke Lidstaat tussen de leeftijd van 13 en 16 jaar. Komen wij erachter dat wij persoonsgegevens van Kinderen hebben verzameld zonder toestemming van hun ouder of voogd, dan verwijderen wij die gegevens van onze servers. Vermoed je dat je kind zonder jouw toestemming persoonsgegevens aan ons heeft verstrekt, neem dan contact op via <a href=\"mailto:hello@thenewwaveit.com\">hello@thenewwaveit.com</a>.</p>\n<h2>Wijzigingen</h2>\n<p>The New Wave IT kan deze Privacy Policy van tijd tot tijd aanpassen. Raadpleeg hem daarom regelmatig. Een aanpassing treedt in werking op het moment dat wij hem op deze pagina publiceren.</p>\n<h2>Contact</h2>\n<p>Heb je vragen over deze Privacy Policy? Neem dan contact op met The New Wave IT via <a href=\"mailto:hello@thenewwaveit.com\">hello@thenewwaveit.com</a>.</p>"}'::jsonb)
on conflict (slug) do update set data = excluded.data || cms_paginas.data;

-- ---------- 3. nieuwe velden op bestaande pagina's ----------
-- `defaults || data` betekent: de bestaande waarde wint, alleen wat ontbreekt
-- wordt aangevuld. Een veld dat een redacteur bewust heeft leeggemaakt blijft
-- dus leeg.
update cms_paginas set data = '{"heroTitleStart": "Waar kunnen we je ", "heroAccent": "mee helpen", "heroLead": "Een gesprek plannen kan, maar een korte vraag stellen mag ook gewoon. Bel, mail, app of kom langs, je zit nergens aan vast.", "verwachtTitel": "Wat je kunt verwachten", "verwacht1Titel": "Voorbereiding", "verwacht1Tekst": "We verdiepen ons vooraf in jouw sector en organisatie, zodat het gesprek meteen de diepte in kan.", "verwacht2Titel": "Het gesprek", "verwacht2Tekst": "20 tot 45 minuten met een practice lead, afhankelijk van je vraag. Over jouw businessvraagstuk, niet over onze diensten.", "verwacht3Titel": "Concreet vervolg", "verwacht3Tekst": "Binnen drie dagen een eerste analyse met mogelijke routes, geheel vrijblijvend.", "manierenKop": "Manieren om contact op te nemen", "manier1Titel": "Bel ons direct", "manier1Tekst": "Op werkdagen tussen 9 en 17 uur krijg je meteen iemand aan de lijn.", "manier2Titel": "Stuur een mail", "manier2Tekst": "Stel je vraag, hoe klein ook. Binnen één werkdag een reactie van een echt mens.", "manier3Titel": "App met ons", "manier3Tekst": "Liever appen? Stuur een berichtje via WhatsApp, we reageren snel.", "manier3Knop": "Start een chat", "manier4Titel": "Plan een gesprek", "manier4Tekst": "20 tot 45 minuten met een practice lead, afhankelijk van je vraag. Vrijblijvend en zonder verkooppraatje.", "manier4Knop": "Plan het gesprek", "expertKop": "Je spreekt met o.a.", "adresTitel": "Bezoekadres", "adresRegel": "Ganzenmarkt 6, Utrecht. Koffie staat klaar", "ctaTitel": "Liever eerst zien wat we voor anderen deden?"}'::jsonb || coalesce(data, '{}'::jsonb)
 where slug = 'contact';
update cms_paginas set data = '{"heroTitleStart": "De ondernemende mens zorgt voor ", "heroAccent": "vooruitgang", "heroLead": "Wij geloven dat succesvolle verandering begint bij mensen. Daarom verzorgen wij alle randvoorwaarden voor onze Wavers, en helpen zij onze partners maximaal digitaal versnellen. Zo staat jouw organisatie klaar voor de dag van overmorgen.", "missieTitel": "Maximale digitale impact, met de mens als maat.", "missieP1": "We richtten The New Wave IT op vanuit één overtuiging: technologie is het middel, de mens is de maat. Wij zijn geen anonieme delivery-machine. Je werkt met mensen die je vraagstuk écht doorgronden, van de eerste sessie tot livegang en daarna.", "missieP2": "Dat doen we door op elk project de mensen te kiezen van wie de ervaring, skills en ambitie het beste passen bij jouw vraagstuk. Ons doel? Dat elk mens werk doet dat aansluit bij zijn of haar persoonlijke doelen en drijfveren.", "teamTitel": "Ontmoet de Wavers.", "teamP1": "Geen anonieme delivery-machine: je kent de mensen die jouw vraagstuk oplossen. Senior consultants en engineers die de taal van de boardroom én de werkvloer spreken, betrokken als partner.", "teamP2": "Van strategische sessies tot livegang en beheer: hetzelfde team blijft aan boord. Zo houden we vaart, kwaliteit en verantwoordelijkheid bij elkaar. Wekelijkse Wavetime-sessies en een jaarlijkse Company week: structurele investering in hoe we sámen werken.", "ctaTitel": "Benieuwd wat onze mensen voor jouw doelen kunnen betekenen?", "waardenKicker": "Waar wij voor staan", "waardenTitel": "Vier overtuigingen die je terugziet in ons werk", "waarde1Titel": "Mens centraal", "waarde1Tekst": "De mens is de centrale factor in het behalen van business doelstellingen, niet de technologie zelf. Beloning is bij ons gelijk en transparant voor iedereen met dezelfde ervaring, ongeacht gender of achtergrond.", "waarde2Titel": "Pragmatisch", "waarde2Tekst": "We rekenen elke oplossing door op wat jouw vraagstuk daadwerkelijk oplost, en zeggen net zo makkelijk nee tegen een hype die dat niet doet.", "waarde3Titel": "Autoriteit door bewijs", "waarde3Tekst": "Bewezen frameworks (App Factory, OGSM, 3-Horizonsmodel) en concrete resultaten, geen losse claims.", "waarde4Titel": "Duurzaam ondernemen", "waarde4Tekst": "Ondernemen en maatschappelijke bijdrage horen bij elkaar. In 2030 is ons businessmodel 100% CO2-neutraal.", "kpi1Getal": "2023", "kpi1Label": "Opgericht, kantoor in Utrecht", "kpi2Getal": "100%", "kpi2Label": "De mens centraal, op elk project", "kpi3Getal": "2030", "kpi3Label": "Doel: CO2-neutraal businessmodel", "missieFotoAlt": "Wavers in gesprek met een klant", "teamFotoAlt": "Het team achter The New Wave IT", "adresRegel": "Ganzenmarkt 6, 3512 GD Utrecht"}'::jsonb || coalesce(data, '{}'::jsonb)
 where slug = 'over-ons';
update cms_paginas set data = '{"heroTitleStart": "Word een ", "heroAccent": "Waver", "heroLead": "Het is onze droom dat elk mens werk doet dat aansluit bij persoonlijke doelen en drijfveren. Wij verzorgen de randvoorwaarden: een gelijk speelveld, een open cultuur en alle ruimte om te groeien. Jij zorgt voor de versnelling bij onze partners.", "ctaTitel": "Eerst een kop koffie? Kom kennismaken.", "groeiKicker": "Groei & ontwikkeling", "groeiTitel": "Elke dag samen beter worden", "groeiIntro": "Persoonlijke aandacht en focus op groei zijn de kern. Samen verkennen we meerdere routes naar jouw ambitie en kiezen we de best passende weg.", "groei1Titel": "Persoonlijk groeipad", "groei1Tekst": "Jouw route bestaat uit activiteiten on-the-job, cursussen en trainingen, gekozen op basis van jouw ambitie, niet een standaardlijstje.", "groei2Titel": "Open feedbackcultuur", "groei2Tekst": "Regelmatige, open en eerlijke feedback hoort bij onze cultuur. Elk half jaar haal je bovendien 360°-feedback op uit je omgeving.", "groei3Titel": "Learning week", "groei3Tekst": "Jaarlijks trekken we er met z''n allen een volle week op uit om samen te ontwikkelen: vakinhoudelijk én persoonlijk.", "tpKicker": "Total People", "tpTitel": "Presteren, groeien én ontspannen", "tpIntro": "Bij ons staat het Total People-principe centraal: de balans tussen presteren, groeien en ontspannen. Jouw groei is onze groei.", "tp1Titel": "Presteren", "tp1Tekst": "Uitdagende opdrachten bij partners in de publieke sector, mobiliteit, banken, zorg en manufacturing. Een rol op maat die jij zelf kiest.", "tp2Titel": "Groeien", "tp2Tekst": "Zeggenschap over de koers: je beslist mee over strategie en investeringen van onze organisatie. Plus een persoonlijk groeipad met open feedback.", "tp3Titel": "Ontspannen", "tp3Tekst": "Werk dat aansluit bij jouw doelen en drijfveren, met ruimte voor rust. Duurzaam onderweg in een elektrische auto van de zaak.", "cultuurKicker": "Onze cultuur", "cultuurTitel": "Ondernemende mensen, gelijk speelveld.", "cultuurP": "Je werkt hier niet vóór ons, je werkt mét ons. Gepassioneerde consultants en engineers die naast klantteams staan en zelf ruimte krijgen om te groeien naar expertrollen.", "cultuur1": "Persoonlijk groeipad, geen vaste carrièreladder", "cultuur2": "Wavetime en Company week als vaste cultuurrituelen", "cultuur3": "Werken met bewezen frameworks (App Factory, OGSM, App in a Day) in plaats van losse projecten", "cultuur4": "Gelijke, transparante beloning bij gelijke ervaring, ongeacht gender of achtergrond", "geenMatchVoor": "Staat jouw rol er niet tussen?", "geenVacatures": "Op dit moment staan er geen vacatures open. We spreken sowieso graag met Mendix- en AI-consultants die bij ons passen.", "openSollLink": "Stuur hieronder een open sollicitatie", "belRegel": "of bel {naam}: {telefoon}.", "openSollKop": "Open sollicitatie", "openSollIntro": "Geen passende vacature? Laat je gegevens achter, we kijken graag of er een match is.", "openSollNoot": "Na je sollicitatie neemt {naam} binnen twee werkdagen contact op. Een echt mens, geen automatische afwijzing.", "cultuurFotoAlt": "Wavers tijdens een kennissessie"}'::jsonb || coalesce(data, '{}'::jsonb)
 where slug = 'werken-bij';

-- ---------- 4. controle ----------
-- Verwacht na afloop, per pagina het aantal sleutels in data:
--   contact 25 | diensten 48 | diensten-ai 7 | diensten-mendix 7
--   diensten-strategie 10 | home 9 | inzichten 11 | klantverhalen 12
--   over-ons 29 | privacy 5 | sectoren 12 | werken-bij 37
select p.slug, p.status, count(k.key) as velden
from cms_paginas p
left join lateral jsonb_object_keys(p.data) as k(key) on true
group by p.slug, p.status
order by p.slug;
